code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Infer the repeating horizontal motif length from the visible patterned area.
    best_period = 5
    best_score = float("inf")
    for period in range(2, min(12, w) + 1):
        errors = 0
        for r in range(3, h):
            buckets = {}
            for c in range(3, w):
                v = grid[r][c]
                if v != 0:
                    buckets.setdefault(c % period, []).append(v)
            errors += sum(len(vals) - Counter(vals).most_common(1)[0][1] for vals in buckets.values())
        score = errors + 0.2 * period
        if score < best_score:
            best_score, best_period = score, period

    out = [row[:] for row in grid]
    for r in range(h):
        if r < 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1
            continue
        for c in range(w):
            if out[r][c] != 0:
                continue
            if c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            elif r == 2:
                out[r][c] = 4
            else:
                vals = [grid[rr][cc] for rr in range(3, h) for cc in range(3, w)
                        if rr == r and cc % best_period == c % best_period and grid[rr][cc] != 0]
                out[r][c] = Counter(vals).most_common(1)[0][0] if vals else 0
    return out
'''
